const int n = std::thread::hardware_concurrency();
std::vector<std::future<double>> parts;
for (int i = 0; i < n; ++i)                     // master partitions
    parts.push_back(std::async(std::launch::async, part, i));
double total = 0;
for (auto& f : parts) total += f.get();          // join + combine

std::vector<std::jthread> pool;
std::queue<Job> q; std::mutex m; std::condition_variable cv;
for (int i = 0; i < n; ++i)
    pool.emplace_back([&](std::stop_token st) {         // slave
        for (;;) {
            Job j;
            { std::unique_lock lk(m); cv.wait(lk, [&]{ return !q.empty() || st.stop_requested(); });
              if (st.stop_requested()) return; j = q.front(); q.pop(); }
            results.push_back(compute(j));              // partial
        }
    });
// master: fill q, cv.notify_all(); on shutdown pool[i].request_stop()

